--- from: Assets/BundleResources/Prefabs/LadderCompetion/LadderCompetionBattleRecordDialog.prefab
---@class LadderCompetionBattleRecordDialog
---@field Env                           	LadderCompetionBattleRecordDialog       
---@field controller                    	Engine.UI.UILuaDialog                   
---@field EmptyNode                     	UnityEngine.RectTransform               
---@field ListView                      	SuperScrollView.LoopGridView            
local LadderCompetionBattleRecordDialog = Class("LadderCompetionBattleRecordDialog")
local RecordCellNodeLuaPath = 'Game.UI.LadderCompetion.LadderCompetionBattleRecordCellNode'

function LadderCompetionBattleRecordDialog:__init()
    self.recordList = {}
end

function LadderCompetionBattleRecordDialog:__delete()
    self.recordList = nil
    self.controller = nil
end

function LadderCompetionBattleRecordDialog:Awake()
end

function LadderCompetionBattleRecordDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util
            .cs_generator(function()
    end))
    return coWait
end

function LadderCompetionBattleRecordDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetAddSortingOrder(self.controller, 5)  -- 为了挡住下面的情绪共鸣特效
        self:RequestRecord_()
    end))
    return coWait
end


function LadderCompetionBattleRecordDialog:RequestRecord_()
    GameUtils.Request(Interfaces.LADDER_RECORD, {},
function(request, response)
            if checkNumber(response.errCode) == 0 then
                local allRecord = checkTable(response.data)

                self.recordList = {}
                for rankIndex, rankData in ipairs(allRecord.record or {}) do
                    local recordDojo = LadderRecordDojo.New()
                    recordDojo:Fill(rankData)
                    self.recordList[rankIndex] = recordDojo
                end
                self:RefreshView_()
            end
        end
    )
end

function LadderCompetionBattleRecordDialog:RefreshView_()
    local hasRecord = #self.recordList > 0
    CfUtils.SetActive(self.EmptyNode, not hasRecord)
    CfUtils.SetActive(self.ListView, hasRecord)
    if hasRecord then
        self:UpdateRecord()
    end
end

function LadderCompetionBattleRecordDialog:UpdateRecord()
    if not self.ListView.IsListViewInit then
        self.ListView:InitGridView(#self.recordList, Bind(self, self.OnUpdateRecordItem))
    else
        self.ListView:MovePanelToItemIndex(0)
    end
end

function LadderCompetionBattleRecordDialog:OnUpdateRecordItem(listView, listIndex)
    if listIndex < 0 then return end
    local cell = listView:NewListViewItem("Cell")
    ---@type LadderCompetionBattleRecordCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, RecordCellNodeLuaPath)
    if nodeEnv then
        local luaIndex = listIndex + 1
        local cellData = checkTable(self.recordList[luaIndex])
        -- init cell
        nodeEnv:SetLuaIndex(luaIndex)
        nodeEnv:SetCellData(cellData)
        nodeEnv:PlayAni()
    end
    return cell
end

function LadderCompetionBattleRecordDialog:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引⽤用到的c#对象
        self:Delete()
    end))
    return coWait
end

return LadderCompetionBattleRecordDialog